from __future__ import annotations

from typing import Any

from alpha_sdk import Context


def add_note(ctx: Context, title: str) -> dict[str, Any]:
    """Save exactly one note, keeping the words the person typed."""
    text = title.strip()
    if not text:
        raise ValueError("A note needs some words.")
    record = ctx.records.create("notes", {"title": text, "noted_on": ctx.today().isoformat()})
    return {"id": record.id, "revision": record.revision}


def count_notes(ctx: Context) -> dict[str, Any]:
    """How many notes are saved in total."""
