package.tests/test_handlers.py:
"""Candidate-authored tests (supplementary evidence only)."""

import sys
import unittest
from datetime import date
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "src"))

from notes_app import handlers  # noqa: E402


class FakeRecord:
    def __init__(self, record_id: str, values: dict) -> None:
        self.id = record_id
        self.revision = 1
        self.values = values


class FakeRecords:
    def __init__(self) -> None:
        self.saved: list[FakeRecord] = []

    def create(self, collection: str, values: dict) -> FakeRecord:
        assert collection == "notes"
        record = FakeRecord(f"rec_{len(self.saved) + 1}", dict(values))
        self.saved.append(record)
        return record

    def all(self, collection: str) -> list:
        assert collection == "notes"
        return list(self.saved)


class FakeContext:
    def __init__(self, day: date = date(2026, 9, 26)) -> None:
        self.records = FakeRecords()
        self._day = day

    def today(self) -> date:
        return self._day


class AddNote(unittest.TestCase):
    def test_saves_one_note_dated_today(self) -> None:
        ctx = FakeContext()

        out = handlers.add_note(ctx, title="Buy milk")

        self.assertEqual(len(ctx.records.saved), 1)
        self.assertEqual(
            ctx.records.saved[0].values, {"title": "Buy milk", "noted_on": "2026-09-26"}
        )
        self.assertEqual(out, {"id": "rec_1", "revision": 1})

    def test_keeps_the_words_as_typed(self) -> None:
        ctx = FakeContext()

        handlers.add_note(ctx, title="  Call the vet  ")

        self.assertEqual(ctx.records.saved[0].values["title"], "Call the vet")

    def test_blank_note_is_refused(self) -> None:
        ctx = FakeContext()

        with self.assertRaises(ValueError):
            handlers.add_note(ctx, title="   ")

        self.assertEqual(ctx.records.saved, [])


class CountNotes(unittest.TestCase):
    def test_counts_every_saved_note(self) -> None:
        ctx = FakeContext()

        self.assertEqual(handlers.count_notes(ctx), {"count": 0})

        handlers.add_note(ctx, title="Buy milk")
        handlers.add_note(ctx, title="Water the plants")

        self.assertEqual(handlers.count_notes(ctx), {"count": 2})


if __name__ == "__main__":
    unittest.main()

